MENU_OPTIONS = ["운동 측정", "이번주 순위", "주간 추첨"]


def sync_menu_to_top():
    st.session_state["main_nav_top"] = st.session_state["main_navigation_v3"]


def sync_menu_to_sidebar():
    st.session_state["main_navigation_v3"] = st.session_state["main_nav_top"]


with st.sidebar:
    st.markdown('<div style="font-size:22px;font-weight:900;color:#2d4934;padding:8px 2px 2px">🌿 운동량 측정</div><div style="font-size:11px;color:#697966;margin:0 0 15px">가족과 함께 움직이는 기록</div>', unsafe_allow_html=True)
    page = st.radio("앱 메뉴", MENU_OPTIONS, key="main_navigation_v3", label_visibility="collapsed", on_change=sync_menu_to_top)

# Keep navigation visible even when Streamlit's collapsible sidebar is closed.
st.markdown('<div style="font-size:12px;font-weight:900;color:#f2efd9;margin:0 0 5px;text-shadow:0 1px 5px rgba(0,0,0,.5)">화면 메뉴</div>', unsafe_allow_html=True)
top_page = st.radio("화면 메뉴", MENU_OPTIONS, key="main_nav_top", horizontal=True, label_visibility="collapsed", on_change=sync_menu_to_sidebar)
page = top_page

start_day = week_start(now_kst().date())
end_day = start_day + timedelta(days=6)
week_label = f"{start_day.strftime('%m.%d')} — {end_day.strftime('%m.%d')}"
hero_copy = {
    "운동 측정": ("운동량 측정", "가족과 함께 움직인 거리와 순위를 기록해요.<br>이번 주 1등을 위한 운동을 시작해 보세요!", f"🍃 이번 주 {week_label} · 로그인 없이 함께 기록"),
    "이번주 순위": ("이번 주 순위", "가족이 함께 쌓은 이번 주 운동 거리를 확인해요.", f"🍃 이번 주 {week_label}"),
    "주간 추첨": ("주간 보상 추첨", "이번 주 1등 가족에게 집안일 면제 보상이 자동 추첨돼요.", "🎁 매주 일요일 오후 6시 · 청소·빨래·설거지"),
}
hero_title, hero_description, hero_badge = hero_copy[page]
st.markdown(
    f'<div class="hero"><div class="hero-copy"><div class="eyebrow">FAMILY MOVE TRACKER</div><h1>{hero_title}</h1><p>{hero_description}</p><span class="hero-badge">{hero_badge}</span></div><img class="hero-mascot" src="{mascot_uri}" alt="숲속 길잡이 캐릭터"></div>',
    unsafe_allow_html=True,
)

# Render the GPS component only on its dedicated screen to avoid hidden iframe remounts.
if page == "운동 측정":
    st.markdown('<div class="section-title">🧭 GPS 운동 측정</div>', unsafe_allow_html=True)
    st.markdown('<div class="section-sub">걷기와 달리기를 함께 기록하고, 시속 15km를 넘는 빠른 이동 구간은 제외해요.</div>', unsafe_allow_html=True)
    if not data["members"]:
        selected_member = None
        st.info("먼저 가족 이름을 추가해 주세요. 아래 ‘가족 구성원 추가’를 열면 등록할 수 있어요.")
    elif st.session_state.tracking_active and st.session_state.tracking_member in data["members"]:
        selected_member = st.session_state.tracking_member
        st.info(f"지금은 **{selected_member}님**의 GPS 운동을 측정 중이에요. 종료 버튼을 눌러 기록을 저장하세요.")
    else:
        selected_member = st.selectbox("운동하는 가족", data["members"], key="member_for_gps")
else:
    selected_member = st.session_state.tracking_member if st.session_state.tracking_active else (data["members"][0] if data["members"] else None)

# Mount the GPS component only on its own screen. This avoids hidden zero-height
# component iframes being reconciled during navigation between pages.
if page == "운동 측정":
    gps_event = gps_tracker(
        active=bool(st.session_state.tracking_active),
        member=selected_member or "",
        key="family_gps_widget_v2",
        default=None,
        height=90,
    )
else:
    gps_event = None
if gps_event and isinstance(gps_event, dict) and gps_event.get("event_id") != st.session_state.last_component_event:
    st.session_state.last_component_event = gps_event.get("event_id")
    event = gps_event.get("event")
    if event == "started":
        reset_tracking()
        st.session_state.tracking_active = True
        st.session_state.tracking_member = selected_member
        st.session_state.tracking_started_at = int(gps_event.get("timestamp", datetime.now().timestamp() * 1000))
    elif event == "point":
        if not st.session_state.tracking_active:
            reset_tracking()
            st.session_state.tracking_active = True
            st.session_state.tracking_member = selected_member
            st.session_state.tracking_started_at = int(gps_event.get("timestamp", datetime.now().timestamp() * 1000))
        current = {
            "lat": float(gps_event.get("lat", 0)),
            "lon": float(gps_event.get("lon", 0)),
            "accuracy": float(gps_event.get("accuracy") or 9999),
            "timestamp": int(gps_event.get("timestamp", 0)),
            "speed": gps_event.get("speed"),
        }
        previous = st.session_state.last_position
        if previous:
            elapsed = (current["timestamp"] - previous["timestamp"]) / 1000.0
            segment_km = haversine_km(previous["lat"], previous["lon"], current["lat"], current["lon"])
            computed_speed = (segment_km * 3600 / elapsed) if elapsed > 0 else 0
            reported_speed = float(current["speed"]) * 3.6 if current["speed"] is not None else 0
            fastest_speed = max(computed_speed, reported_speed)
            accuracy_ok = current["accuracy"] <= 40 and previous["accuracy"] <= 40
            if elapsed > 0 and elapsed <= 180 and accuracy_ok:
                if fastest_speed > SPEED_LIMIT_KMH:
                    st.session_state.ignored_fast += 1
                elif segment_km >= 0.004:
                    st.session_state.tracking_distance += segment_km
                    st.session_state.tracking_points += 1
        st.session_state.last_position = current
    elif event == "stopped":
        distance_km = float(st.session_state.tracking_distance)
        member_name = st.session_state.tracking_member or selected_member
        if distance_km >= 0.02:
            updated = json.loads(json.dumps(data, ensure_ascii=False))
            duration = max(0, int((int(gps_event.get("timestamp", datetime.now().timestamp() * 1000)) - int(st.session_state.tracking_started_at or gps_event.get("timestamp", 0))) / 1000))
            updated["activities"].append({"id": datetime.now().strftime("%Y%m%d%H%M%S%f"), "member": member_name, "distance": round(distance_km, 3), "date": now_kst().date().isoformat(), "duration_seconds": duration, "source": "GPS"})
            error = persist(updated, data_sha, storage)
            if error:
                st.session_state.flash_message = f"기록 저장에 실패했어요: {error}"
            else:
                st.session_state.flash_message = f"{member_name}님의 GPS 거리 {distance_km:.2f}km를 저장했어요!"
        else:
            st.session_state.flash_message = "측정된 거리가 너무 짧아 기록하지 않았어요."
        st.session_state.tracking_active = False
        reset_tracking()
        st.rerun()
    elif event == "error":
        st.session_state.tracking_active = False
        st.session_state.flash_message = f"GPS 오류: {gps_event.get('message', '위치 권한을 확인해 주세요.')}"
        reset_tracking()

if st.session_state.flash_message:
    st.success(st.session_state.flash_message) if "저장" in st.session_state.flash_message else st.warning(st.session_state.flash_message)
    st.session_state.flash_message = None

if page == "운동 측정":
    if st.session_state.tracking_active:
        started = st.session_state.tracking_started_at or int(datetime.now().timestamp() * 1000)
        elapsed_seconds = max(0, int(datetime.now().timestamp() - started / 1000))
        elapsed_text = f"{elapsed_seconds // 60:02d}:{elapsed_seconds % 60:02d}"
        st.markdown(
            f'<div class="tracker-shell"><span class="tracker-tag">● GPS LIVE</span><div class="live-distance">{st.session_state.tracking_distance:.2f} <span style="font-size:15px">km</span></div><div class="live-meta">운동 시간 {elapsed_text} · 유효 위치 구간 {st.session_state.tracking_points}개 · 빠른 이동 제외 {st.session_state.ignored_fast}회</div></div>',
            unsafe_allow_html=True,
        )

    st.caption("GPS 사용에는 위치 권한이 필요해요. 좌표는 저장하지 않고, 운동을 종료할 때 거리만 가족 기록에 저장해요.")

weekly = week_activities(data)
weekly_totals = totals_by_member(data["members"], weekly)
all_totals = totals_by_member(data["members"], data["activities"])
ranked = sorted(weekly_totals.items(), key=lambda item: (-item[1], item[0]))
leader = ranked[0] if ranked and ranked[0][1] > 0 else None
week_total = sum(weekly_totals.values())

if page == "이번주 순위":
    st.markdown('<div class="section-title">🏆 이번 주 가족 순위</div>', unsafe_allow_html=True)
    st.markdown('<div class="section-sub">월요일부터 일요일까지 GPS로 측정된 거리만 집계해요.</div>', unsafe_allow_html=True)
    k1, k2, k3 = st.columns(3)
    for col, label, value, note in [
        (k1, "가족 총 거리", f"{week_total:.2f} km", "이번 주 함께 모은 거리"),
        (k2, "활동 기록", f"{len(weekly)}회", "GPS 측정을 마친 횟수"),
        (k3, "현재 챔피언", leader[0] if leader else "기록 기다리는 중", f"{leader[1]:.2f} km" if leader else "첫 기록의 주인공은 누구?") ,
    ]:
        with col:
            st.markdown(f'<div class="stat-card"><div class="stat-label">{label}</div><div class="stat-value">{value}</div><div class="stat-note">{note}</div></div>', unsafe_allow_html=True)

    max_distance = max((value for _, value in ranked), default=0)
    if max_distance <= 0:
        st.info("이번 주 첫 GPS 모험을 시작해 보세요!")
    else:
        for idx, (name, distance) in enumerate(ranked, start=1):
            medal = "🥇" if idx == 1 and distance > 0 else ("🥈" if idx == 2 and distance > 0 else ("🥉" if idx == 3 and distance > 0 else str(idx)))
            width = max(4, int(distance / max_distance * 100)) if distance else 0
            rank_class = "first" if idx == 1 and distance > 0 else ""
            st.markdown(f'<div class="rank-card"><div class="rank-no {rank_class}">{medal}</div><div style="flex:1"><div class="rank-name">{name}</div><div class="track"><div class="fill" style="width:{width}%"></div></div></div><div class="rank-distance">{distance:.2f} <span style="font-size:11px;color:#879183">km</span></div></div>', unsafe_allow_html=True)


# Scheduled GitHub Action is the primary Sunday 18:00 trigger. This is a fallback
# for an active app session if the scheduled job has not written this week's result yet.
weekly_draw_now = now_kst()
weekly_reward = data.get("rewards", {}).get(current_week_key())
if weekly_draw_now.weekday() == 6 and (weekly_draw_now.hour, weekly_draw_now.minute) >= (18, 0) and not weekly_reward and leader:
    top_distance = max(weekly_totals.values(), default=0)
    top_members = [name for name, value in weekly_totals.items() if value == top_distance and value > 0]
    if top_members:
        winner = random.SystemRandom().choice(top_members)
        prize_number = random.SystemRandom().randint(1, len(REWARDS))
        updated = json.loads(json.dumps(data, ensure_ascii=False))
        updated.setdefault("rewards", {})[current_week_key()] = {
            "member": winner,
            "prize": REWARDS[prize_number - 1],
            "ball_number": prize_number,
            "drawn_at": weekly_draw_now.isoformat(timespec="seconds"),
        }
        try:
            data_sha = save_data(updated, data_sha, storage)
            data = updated
            weekly_reward = updated["rewards"][current_week_key()]
        except Exception as exc:
            st.error(f"이번 주 자동 추첨 결과를 저장하지 못했어요: {exc}")

if page == "주간 추첨":
    st.markdown('<div class="section-title">🎱 주간 면제 보상 추첨</div>', unsafe_allow_html=True)
    st.markdown('<div class="section-sub">이번 주 1등 가족을 기준으로 매주 일요일 오후 6시에 자동 추첨돼요.</div>', unsafe_allow_html=True)
    reward = data["rewards"].get(current_week_key())
    ball_number = None
    if reward:
        ball_number = int(reward.get("ball_number", REWARDS.index(reward["prize"]) + 1))
    draw_animation = False
    if reward:
        try:
            drawn_at = datetime.fromisoformat(reward.get("drawn_at", ""))
            if drawn_at.tzinfo is None:
                drawn_at = drawn_at.replace(tzinfo=ZoneInfo("Asia/Seoul"))
            draw_animation = (weekly_draw_now - drawn_at.astimezone(ZoneInfo("Asia/Seoul"))).total_seconds() < 180
        except (ValueError, TypeError):
            draw_animation = False
    machine_class = "machine is-drawing" if draw_animation else "machine"
    balls_markup = ''.join(
        f'<div class="lotto-ball ball-{css_name}">{number:02d}</div>'
        for number, (css_name, _) in enumerate([("one", "청소"), ("two", "빨래"), ("three", "설거지")], start=1)
    )
    if reward:
        prize_display = f'<span class="winner-ball">{ball_number:02d}</span><span>{reward["prize"]}</span>'
        prize_slot_class = "prize-slot"
    else:
        prize_display = '<span>행운의 공이 여기에 나와요</span>'
        prize_slot_class = "prize-slot empty"
    st.markdown(
        f'''<div class="lotto-stage">
          <div class="lotto-stage-title">우리 가족 면제권 추첨기</div>
          <div class="lotto-stage-copy">공이 흔들리며 추첨통에서 하나씩 뽑혀요</div>
          <div class="{machine_class}">
            <div class="machine-globe">{balls_markup}</div>
            <div class="machine-neck"></div>
            <div class="machine-base"><div class="machine-brand">FAMILY WEEKLY LOTTO</div>
              <div class="{prize_slot_class}">{prize_display}</div>
            </div>
          </div>
          <div class="lotto-legend"><span class="lotto-chip">01 · 청소 면제</span><span class="lotto-chip">02 · 빨래 면제</span><span class="lotto-chip">03 · 설거지 면제</span></div>
        </div>''',
        unsafe_allow_html=True,
    )
    if reward:
        st.markdown(f'<div class="lotto-result-text">🎟️ {html.escape(str(reward["prize"]))}<small>이번 주 1등 · {html.escape(str(reward["member"]))}</small></div>', unsafe_allow_html=True)
        st.caption(f"추첨 시각: {reward.get('drawn_at', '기록됨')} · 다음 추첨은 일요일 오후 6시예요.")
    elif leader:
        st.markdown(f'<div style="text-align:center;margin:12px 0 8px;color:#f3eedc">현재 1등 <b>{html.escape(leader[0])}</b>님 · 일요일 오후 6시에 자동 추첨</div>', unsafe_allow_html=True)
        st.info("일요일 오후 6시가 되면 청소·빨래·설거지 면제권 중 하나가 자동으로 정해져요.")
    else:
        st.info("이번 주 운동 기록이 아직 없어요. 운동 기록이 있으면 주간 1등에게 일요일 오후 6시에 보상이 추첨됩니다.")

if page == "운동 측정":
    with st.expander("👨‍👩‍👧 가족 구성원 추가"):
        with st.form("add_member", clear_on_submit=True):
            new_member = st.text_input("이름 또는 별명", max_chars=24, placeholder="예: 엄마, 민수")
            add = st.form_submit_button("가족 추가")
        if add:
            name = new_member.strip()
            if not name:
                st.warning("이름을 입력해 주세요.")
            elif name in data["members"]:
                st.warning("이미 등록된 이름이에요.")
            else:
                updated = json.loads(json.dumps(data, ensure_ascii=False))
                updated["members"].append(name)
                error = persist(updated, data_sha, storage)
                if error:
                    st.error(f"가족 추가 실패: {error}")
                else:
                    st.success(f"{name}님을 가족 챌린지에 추가했어요!")
                    st.rerun()

if page == "운동 측정":
    st.markdown('<div class="section-title">📜 최근 운동 기록</div>', unsafe_allow_html=True)
    recent = sorted(data["activities"], key=lambda a: (a.get("date", ""), a.get("id", "")), reverse=True)[:10]
    if not recent:
        st.caption("아직 저장된 GPS 모험이 없어요.")
    else:
        for item in recent:
            mins = int(item.get("duration_seconds", 0)) // 60
            st.markdown(f'🌿 **{item.get("member", "가족")}** · **{float(item.get("distance", 0)):.2f} km** · {mins}분 <span style="color:#8b9485">· {item.get("date", "")}</span>', unsafe_allow_html=True)


if page == "이번주 순위":
    with st.expander("가족별 누적 거리 보기"):
        for name, distance in sorted(all_totals.items(), key=lambda item: (-item[1], item[0])):
            st.write(f"**{name}**　{distance:.2f} km")


if storage == "github":
    st.markdown('<div class="footnote">가족 기록은 연결된 GitHub 저장소에 저장돼요. 좌표는 남기지 않아요.</div>', unsafe_allow_html=True)
else:
    st.markdown('<div class="footnote">로컬 미리보기 저장 모드 · 가족끼리 같은 기록을 쓰려면 Streamlit Secrets에 GitHub 저장소를 연결해 주세요.</div>', unsafe_allow_html=True)
